const e="Ils ne sont pas venus du Nord. Ils y sont restés.",t="Chroniques des explorateurs de Nordheim",n=["Peuple & Lignée","Valm du Nord","Codex #PEU-012"],s=[1,11,12],o="Nordheim (Régions septentrionales)",i="Résistance au froid, Navigation, Chasse",a="165cm - 190cm",r="80",l="« Hommes du Nord »",c="Skaal_icone.jpeg",u="Commun à Nordheim",d=[{title:"Présentation",type:"text",content:"Les Skurf sont des Valm dont les ancêtres s'installèrent à Nordheim bien avant sa redécouverte par le Vieux Monde. Des siècles d'isolement ont forgé une identité et une culture propres."},{title:"Culture & Survie",type:"text",content:"Leur société privilégie l'honneur de la parole donnée, la solidarité clansale, la chasse et l'endurance face au climat polaire."},{title:"Relations avec les autres peuples",type:"politique_list_long",content:[{headline:"Neutre / Fraternel",title:"Les Morndal",content:"Entretiennent d'excellentes relations d'entraide et de commerce en montagne.",color:"#34D399"},{headline:"Rivalité culturelle",title:"Les Valm de Barkovie",content:"Bien qu'humains, leurs modes de vie et croyances religieuses diffèrent vivement.",color:"#C29B38"}]},{title:"Aujourd'hui",type:"text",content:"Les Skurf vivent organisés en communautés autonomes le long des côtes et vallées de Nordheim."}],m={citation:e,citation_author:t,tags:n,link_articles:s,class:"Humaine (Adaptée)",repart:o,trait:i,height:a,age:r,surname:l,image:c,statut:u,sections:d};export{r as age,e as citation,t as citation_author,m as default,a as height,c as image,s as link_articles,o as repart,d as sections,u as statut,l as surname,n as tags,i as trait};
